            boolean carried = (then.equals("OPEN") || then.equals("PENDING")) && earlier.stream()
                    .anyMatch(q -> !on.isBefore(LocalDate.parse(q.from())) && !on.isAfter(LocalDate.parse(q.to())));
            if (!in && !carried) continue;
